/* Lanka Global Access — Course Finder
 * Data: window.LGA_COURSE_DATA (assets/js/data/courses.js, generated by scraper/organize.py)
 *       assets/js/data/summaries/<universityId>.json (program summaries, fetched when a course is opened)
 * Features: faceted filters with live counts, sorting, grid/list views, paging,
 * shareable URL state, saved-course shortlist and a course detail dialog.
 */
(function () {
    'use strict';

    const PAGE_SIZE = 24;
    const SAVED_KEY = 'lga-saved-courses-v2';
    const SUMMARIES_DIR = 'assets/js/data/summaries/';
    const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

    const COUNTRY_META = {
        australia: { name: 'Australia', icon: 'fa-earth-oceania', color: '#B45309', tint: '#FEF3C7', guide: 'study-abroad/australia.html' },
        canada: { name: 'Canada', icon: 'fa-leaf', color: '#B91C1C', tint: '#FEE2E2', guide: 'study-abroad/canada.html' },
        uk: { name: 'United Kingdom', icon: 'fa-crown', color: '#1D4ED8', tint: '#DBEAFE', guide: 'study-abroad/uk.html' },
        usa: { name: 'USA', icon: 'fa-flag-usa', color: '#0B1F3A', tint: '#E0E7F1', guide: 'study-abroad/usa.html' },
        'new-zealand': { name: 'New Zealand', icon: 'fa-mountain-sun', color: '#047857', tint: '#D1FAE5', guide: 'study-abroad/new-zealand.html' },
    };

    const FIELD_ICONS = {
        'Business & Management': 'fa-briefcase',
        'Computing & IT': 'fa-laptop-code',
        'Data & Analytics': 'fa-chart-line',
        'Engineering & Construction': 'fa-gears',
        'Health & Nursing': 'fa-heart-pulse',
        'Science & Environment': 'fa-flask',
        'Law & Criminology': 'fa-scale-balanced',
        'Education & Teaching': 'fa-chalkboard-user',
        'Hospitality & Tourism': 'fa-plane',
        'Arts, Media & Design': 'fa-palette',
        'Social Sciences & Psychology': 'fa-brain',
        Other: 'fa-graduation-cap',
    };

    const DURATIONS = [
        { key: 'lt1', label: 'Up to 1 year', test: m => m <= 12 },
        { key: '1to2', label: '1–2 years', test: m => m > 12 && m <= 24 },
        { key: '2to3', label: '2–3 years', test: m => m > 24 && m <= 36 },
        { key: '3to4', label: '3–4 years', test: m => m > 36 && m <= 48 },
        { key: 'gt4', label: 'More than 4 years', test: m => m > 48 },
    ];

    /* ---------- helpers ---------- */
    const $ = id => document.getElementById(id);
    const esc = value => String(value ?? '').replace(/[&<>"']/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[ch]);
    const fmtInt = n => Number(n).toLocaleString('en-US');
    function parseDate(iso) {
        if (!iso) return null;
        const [y, m, d] = iso.split('-').map(Number);
        return new Date(y, (m || 1) - 1, d || 1);
    }
    const fmtMonth = iso => { const d = parseDate(iso); return d ? `${MONTHS[d.getMonth()]} ${d.getFullYear()}` : ''; };
    const fmtDay = iso => { const d = parseDate(iso); return d ? `${d.getDate()} ${MONTHS[d.getMonth()]} ${d.getFullYear()}` : ''; };
    function durationText(min, max) {
        if (!max) return '—';
        const unit = m => (m % 12 === 0 ? `${m / 12} yr${m === 12 ? '' : 's'}` : m % 6 === 0 && m > 12 ? `${(m / 12).toFixed(1)} yrs` : `${m} mo`);
        return min && min !== max ? `${unit(min)} – ${unit(max)}` : unit(max);
    }
    function hashKey(text) {
        let h = 2166136261;
        for (let i = 0; i < text.length; i += 1) { h ^= text.charCodeAt(i); h = Math.imul(h, 16777619); }
        return (h >>> 0).toString(36);
    }
    function initials(name) {
        const words = name.replace(/[()]/g, '').split(/\s+/).filter(w => w && !/^(of|the|and|at|in|for|&|-|–)$/i.test(w));
        return (words.length === 1 ? words[0].slice(0, 2) : words.slice(0, 2).map(w => w[0]).join('')).toUpperCase();
    }
    const daysUntil = iso => { const d = parseDate(iso); return d ? Math.ceil((d - new Date()) / 86400000) : Infinity; };
    const storage = {
        read() { try { return new Set(JSON.parse(localStorage.getItem(SAVED_KEY) || '[]')); } catch (e) { return new Set(); } },
        write(set) { try { localStorage.setItem(SAVED_KEY, JSON.stringify([...set])); } catch (e) { /* private mode */ } },
    };

    /* ---------- data ---------- */
    function buildCourses(data) {
        const today = new Date();
        today.setHours(0, 0, 0, 0);
        return data.courses.map(row => {
            const uni = data.universities[row.u];
            const intakes = (row.i || [])
                .map(([start, deadline]) => ({ start, deadline }))
                .filter(i => parseDate(i.start) >= today);
            const course = {
                key: row.k,
                name: row.n,
                subject: row.s,
                level: data.levels[row.l],
                field: row.f,
                uni: uni.n,
                uniId: uni.id,
                uniType: uni.t,
                logo: uni.lg || null,
                province: uni.p,
                city: row.ci || uni.ci[0] || '',
                campuses: row.cp || [],
                country: uni.c,
                dMin: row.d && row.d[0],
                dMax: row.d && row.d[1],
                intakes,
                nextIntake: intakes[0] || null,
                nextDeadline: intakes.map(i => i.deadline).find(d => d && parseDate(d) >= today) || null,
                months: new Set(intakes.map(i => parseDate(i.start).getMonth())),
                hasSummary: !!row.x,
                officialUrl: /^https:\/\//.test(row.o || '') ? row.o : '',
            };
            course.uniHref = `universities/${encodeURIComponent(course.country)}/${encodeURIComponent(course.uniId)}.html`;
            course.search = [course.name, course.subject, course.field, course.level, course.uni, course.city,
                course.province, course.campuses.join(' '), COUNTRY_META[course.country]?.name || course.country].join(' ').toLowerCase();
            return course;
        });
    }

    /* Recommended order: interleave countries, and universities within each
     * country (stable pseudo-random order), so the first page shows breadth. */
    function recommendedOrder(courses) {
        const byCountry = new Map();
        courses.forEach(c => {
            if (!byCountry.has(c.country)) byCountry.set(c.country, new Map());
            const unis = byCountry.get(c.country);
            if (!unis.has(c.uni)) unis.set(c.uni, []);
            unis.get(c.uni).push(c);
        });
        const lanes = [...byCountry.values()].map(unis => {
            const queues = [...unis.entries()]
                .sort((a, b) => (b[1].length >= 5) - (a[1].length >= 5) || hashKey(a[0]).localeCompare(hashKey(b[0])))
                .map(([, list]) => list);
            const out = [];
            const total = queues.reduce((n, q) => n + q.length, 0);
            for (let depth = 0; out.length < total; depth += 1) queues.forEach(q => { if (q[depth]) out.push(q[depth]); });
            return out;
        });
        let rank = 0;
        for (let depth = 0; lanes.some(l => depth < l.length); depth += 1) {
            lanes.forEach(l => { if (l[depth]) l[depth].rank = rank++; });
        }
    }

    /* ---------- program summaries (lazy) ---------- */
    const summaryCache = new Map();
    function loadSummaries(uniId) {
        if (!summaryCache.has(uniId)) {
            summaryCache.set(uniId, fetch(`${SUMMARIES_DIR}${encodeURIComponent(uniId)}.json`, { credentials: 'same-origin' })
                .then(r => (r.ok ? r.json() : {}))
                .catch(() => ({})));
        }
        return summaryCache.get(uniId);
    }

    /* ---------- state ---------- */
    const FACETS = ['level', 'country', 'field', 'type', 'dur', 'month'];
    const state = {
        q: '', level: new Set(), country: new Set(), field: new Set(), type: new Set(), dur: new Set(),
        month: new Set(), uni: '', saved: false, sort: 'recommended', view: 'grid', shown: PAGE_SIZE,
    };

    function readUrl() {
        const p = new URLSearchParams(location.search);
        state.q = p.get('q') || '';
        FACETS.forEach(f => { state[f] = new Set((p.get(f) || '').split(',').filter(Boolean)); });
        state.saved = p.get('saved') === '1';
        state.uni = p.get('uni') || '';
        state.sort = SORTERS[p.get('sort')] ? p.get('sort') : 'recommended';
        try { state.view = localStorage.getItem('lga-course-view') || 'grid'; } catch (e) { /* ignore */ }
        return p.get('course');
    }

    function writeUrl(key) {
        const p = new URLSearchParams();
        if (state.q) p.set('q', state.q);
        FACETS.forEach(f => { if (state[f].size) p.set(f, [...state[f]].join(',')); });
        if (state.uni) p.set('uni', state.uni);
        if (state.saved) p.set('saved', '1');
        if (state.sort !== 'recommended') p.set('sort', state.sort);
        if (key) p.set('course', key);
        const qs = p.toString();
        history.replaceState(null, '', qs ? `?${qs}${location.hash}` : location.pathname + location.hash);
    }

    function matches(c, skip) {
        if (state.q) {
            const terms = state.q.toLowerCase().split(/\s+/).filter(Boolean);
            if (!terms.every(t => c.search.includes(t))) return false;
        }
        if (skip !== 'level' && state.level.size && !state.level.has(c.level)) return false;
        if (skip !== 'country' && state.country.size && !state.country.has(c.country)) return false;
        if (skip !== 'field' && state.field.size && !state.field.has(c.field)) return false;
        if (skip !== 'type' && state.type.size && !state.type.has(c.uniType)) return false;
        if (skip !== 'dur' && state.dur.size && !DURATIONS.some(d => state.dur.has(d.key) && c.dMax && d.test(c.dMax))) return false;
        if (skip !== 'month' && state.month.size && ![...state.month].some(m => c.months.has(Number(m)))) return false;
        if (state.uni && c.uniId !== state.uni) return false;
        if (state.saved && !saved.has(c.key)) return false;
        return true;
    }

    const SORTERS = {
        recommended: (a, b) => a.rank - b.rank,
        intake: (a, b) => (a.nextIntake?.start || '9999').localeCompare(b.nextIntake?.start || '9999') || a.rank - b.rank,
        deadline: (a, b) => (a.nextDeadline || '9999').localeCompare(b.nextDeadline || '9999') || a.rank - b.rank,
        duration: (a, b) => (a.dMax || 999) - (b.dMax || 999) || a.rank - b.rank,
        name: (a, b) => a.name.localeCompare(b.name),
        university: (a, b) => a.uni.localeCompare(b.uni) || a.name.localeCompare(b.name),
    };

    let courses = [];
    let data = null;
    let saved = new Set();

    /* ---------- facet panel ---------- */
    function facetOptions() {
        const fields = [...new Set(courses.map(c => c.field))].sort((a, b) => (a === 'Other') - (b === 'Other') || a.localeCompare(b));
        const countries = Object.keys(COUNTRY_META).filter(k => courses.some(c => c.country === k));
        return {
            level: data.levels.map(l => [l, l]),
            country: countries.map(k => [k, COUNTRY_META[k].name]),
            field: fields.map(f => [f, f]),
            type: [...new Set(courses.map(c => c.uniType))].sort().map(t => [t, t]),
            dur: DURATIONS.map(d => [d.key, d.label]),
        };
    }

    function buildFacetPanel() {
        const opts = facetOptions();
        const group = (facet, title, icon, open = true) => `
            <details class="group py-4 first:pt-0" ${open ? 'open' : ''}>
                <summary class="flex cursor-pointer list-none items-center justify-between text-sm font-bold text-[#0B1F3A]">
                    <span><i class="fas ${icon} mr-2 w-4 text-center text-[#C9A45C]" aria-hidden="true"></i>${title}</span>
                    <i class="fas fa-chevron-down text-xs text-gray-400 transition group-open:rotate-180" aria-hidden="true"></i>
                </summary>
                <fieldset class="mt-3 space-y-1.5">
                    <legend class="sr-only">${title}</legend>
                    ${opts[facet].map(([value, label]) => `
                        <label class="flex cursor-pointer items-center gap-2.5 rounded-lg px-1.5 py-1 text-sm text-gray-700 hover:bg-gray-50">
                            <input type="checkbox" class="cf-check shrink-0 rounded" data-facet="${facet}" value="${esc(value)}">
                            <span class="flex-1 leading-snug">${esc(label)}</span>
                            <span class="rounded-full bg-gray-100 px-2 text-xs font-semibold tabular-nums text-gray-500" data-count></span>
                        </label>`).join('')}
                </fieldset>
            </details>`;

        $('cf-facets').innerHTML = `
            ${group('level', 'Study level', 'fa-user-graduate')}
            ${group('country', 'Destination', 'fa-earth-americas')}
            ${group('field', 'Field of study', 'fa-book-open')}
            <details class="group py-4" open>
                <summary class="flex cursor-pointer list-none items-center justify-between text-sm font-bold text-[#0B1F3A]">
                    <span><i class="fas fa-calendar-days mr-2 w-4 text-center text-[#C9A45C]" aria-hidden="true"></i>Intake month</span>
                    <i class="fas fa-chevron-down text-xs text-gray-400 transition group-open:rotate-180" aria-hidden="true"></i>
                </summary>
                <div class="mt-3 grid grid-cols-4 gap-1.5" role="group" aria-label="Intake month">
                    ${MONTHS.map((m, i) => `<button type="button" class="cf-chip rounded-lg border border-gray-200 py-1.5 text-xs font-semibold text-gray-600 transition hover:border-[#C9A45C] disabled:opacity-35" data-month="${i}" aria-pressed="false">${m}</button>`).join('')}
                </div>
            </details>
            ${group('dur', 'Course length', 'fa-hourglass-half', false)}
            ${group('type', 'Institution type', 'fa-building-columns', false)}`;
    }

    function updateFacetPanel() {
        const count = {
            level: (pool, v) => pool.filter(c => c.level === v).length,
            country: (pool, v) => pool.filter(c => c.country === v).length,
            field: (pool, v) => pool.filter(c => c.field === v).length,
            type: (pool, v) => pool.filter(c => c.uniType === v).length,
            dur: (pool, v) => { const d = DURATIONS.find(x => x.key === v); return pool.filter(c => c.dMax && d.test(c.dMax)).length; },
        };
        Object.keys(count).forEach(facet => {
            const pool = courses.filter(c => matches(c, facet));
            document.querySelectorAll(`input[data-facet="${facet}"]`).forEach(input => {
                const n = count[facet](pool, input.value);
                input.checked = state[facet].has(input.value);
                const row = input.closest('label');
                row.querySelector('[data-count]').textContent = fmtInt(n);
                row.classList.toggle('opacity-45', n === 0 && !input.checked);
            });
        });
        const monthPool = courses.filter(c => matches(c, 'month'));
        document.querySelectorAll('[data-month]').forEach(btn => {
            const m = Number(btn.dataset.month);
            const n = monthPool.filter(c => c.months.has(m)).length;
            btn.setAttribute('aria-pressed', String(state.month.has(String(m))));
            btn.disabled = n === 0 && !state.month.has(String(m));
            btn.title = `${fmtInt(n)} courses with a ${MONTHS[m]} intake`;
        });
    }

    /* ---------- active filters ---------- */
    function activeFilters() {
        const items = [];
        const label = (facet, value) => {
            if (facet === 'country') return COUNTRY_META[value]?.name || value;
            if (facet === 'dur') return DURATIONS.find(d => d.key === value)?.label || value;
            if (facet === 'month') return `${MONTHS[Number(value)]} intake`;
            return value;
        };
        if (state.q) items.push(['q', '', `“${state.q}”`]);
        if (state.uni) items.push(['uni', '', `At ${courses.find(c => c.uniId === state.uni)?.uni || state.uni}`]);
        FACETS.forEach(f => state[f].forEach(v => items.push([f, v, label(f, v)])));
        if (state.saved) items.push(['saved', '', 'Saved only']);
        $('cf-active').innerHTML = items.map(([f, v, text]) => `
            <button type="button" class="inline-flex items-center gap-1.5 rounded-full bg-[#0B1F3A]/5 py-1 pl-3 pr-2 text-xs font-semibold text-[#0B1F3A] transition hover:bg-[#0B1F3A]/10" data-remove="${f}" data-value="${esc(v)}" aria-label="Remove filter ${esc(text)}">
                ${esc(text)} <i class="fas fa-xmark text-[10px] text-gray-500" aria-hidden="true"></i>
            </button>`).join('') + (items.length > 1 ? '<button type="button" data-action="clear" class="px-2 text-xs font-semibold text-[#8A6A32] hover:underline">Clear all</button>' : '');
        const facetCount = items.filter(c => c[0] !== 'q').length;
        const badge = $('cf-filter-badge');
        badge.textContent = facetCount;
        badge.classList.toggle('hidden', facetCount === 0);
    }

    /* ---------- logo / monogram ---------- */
    function logoBox(c, size = 'h-11 w-11', text = 'text-sm') {
        const meta = COUNTRY_META[c.country] || COUNTRY_META.usa;
        const fallback = `<span class="cf-logo-fallback flex h-full w-full items-center justify-center font-extrabold tracking-tight ${text}" style="background:${meta.tint};color:${meta.color}">${esc(initials(c.uni))}</span>`;
        if (!c.logo) return `<span class="flex ${size} shrink-0 overflow-hidden rounded-xl" aria-hidden="true">${fallback}</span>`;
        return `<span class="cf-logo flex ${size} shrink-0 items-center justify-center overflow-hidden rounded-xl border border-gray-100 bg-white p-1" aria-hidden="true">
            <img src="${esc(c.logo)}" alt="" loading="lazy" decoding="async" referrerpolicy="no-referrer" class="max-h-full max-w-full object-contain" data-fallback="${esc(initials(c.uni))}">
        </span>`;
    }

    /* Swap a broken logo for the initials monogram (event delegation, capture). */
    document.addEventListener('error', e => {
        const img = e.target;
        if (!(img instanceof HTMLImageElement) || !img.dataset.fallback) return;
        const box = img.parentElement;
        const country = img.closest('[data-country]')?.dataset.country;
        const meta = COUNTRY_META[country] || COUNTRY_META.usa;
        box.classList.remove('border', 'border-gray-100', 'bg-white', 'p-1');
        box.innerHTML = `<span class="flex h-full w-full items-center justify-center text-sm font-extrabold" style="background:${meta.tint};color:${meta.color}">${esc(img.dataset.fallback)}</span>`;
    }, true);

    /* ---------- cards ---------- */
    function card(c) {
        const meta = COUNTRY_META[c.country] || { name: c.country, icon: 'fa-globe' };
        const isSaved = saved.has(c.key);
        const location = [c.city, meta.name].filter(Boolean).join(', ');
        return `
        <article class="cf-card group flex flex-col overflow-hidden rounded-2xl border border-slate-200/80 bg-white shadow-sm transition duration-200 hover:-translate-y-0.5 hover:border-[#C9A45C]/50 hover:shadow-lg" data-country="${esc(c.country)}">
            <div class="cf-card-main flex flex-1 flex-col p-5">
                <div class="mb-4 flex items-start gap-3">
                    ${logoBox(c)}
                    <div class="min-w-0 flex-1">
                        <a href="${c.uniHref}" class="block truncate text-sm font-bold text-[#0B1F3A] hover:text-[#8A6A32] hover:underline" title="View ${esc(c.uni)} profile">${esc(c.uni)}</a>
                        <p class="truncate text-xs text-gray-500"><i class="fas ${meta.icon} mr-1 text-[#A9813F]" aria-hidden="true"></i>${esc(location)}${c.campuses.length > 1 ? ` · ${c.campuses.length} campuses` : ''}</p>
                    </div>
                    <button type="button" class="-mr-1 -mt-1 flex h-9 w-9 shrink-0 items-center justify-center rounded-full transition hover:bg-rose-50 ${isSaved ? 'text-rose-500' : 'text-gray-300 hover:text-rose-400'}" data-save="${c.key}" aria-pressed="${isSaved}" aria-label="${isSaved ? 'Remove from saved' : 'Save course'}: ${esc(c.name)}"><i class="fa${isSaved ? 's' : 'r'} fa-heart" aria-hidden="true"></i></button>
                </div>
                <p class="mb-1.5 text-xs font-bold uppercase tracking-wider text-[#A9813F]">${esc(c.level)} <span class="text-gray-300">·</span> <span class="text-gray-500">${esc(c.field)}</span></p>
                <h3 class="text-[15px] font-bold leading-snug text-[#0B1F3A]">
                    <button type="button" class="text-left hover:text-[#8A6A32] hover:underline decoration-[#C9A45C]/50 underline-offset-4" data-open="${c.key}">${esc(c.name)}</button>
                </h3>
            </div>
            <div class="cf-card-side flex flex-col border-t border-gray-100 bg-[#FAFAFB] p-5">
                <dl class="grid grid-cols-2 gap-x-3 gap-y-3 text-sm">
                    <div><dt class="text-xs font-semibold uppercase tracking-wider text-gray-400">Duration</dt><dd class="font-bold text-[#0B1F3A]">${esc(durationText(c.dMin, c.dMax))}</dd></div>
                    <div><dt class="text-xs font-semibold uppercase tracking-wider text-gray-400">Study level</dt><dd class="font-bold text-[#0B1F3A]">${esc(c.level)}</dd></div>
                    <div><dt class="text-xs font-semibold uppercase tracking-wider text-gray-400">Next intake</dt><dd class="font-bold text-[#0B1F3A]">${c.nextIntake ? esc(fmtMonth(c.nextIntake.start)) : '<span class="text-gray-400">TBC</span>'}</dd></div>
                    <div><dt class="text-xs font-semibold uppercase tracking-wider text-gray-400">Apply by</dt><dd class="font-bold ${c.nextDeadline && daysUntil(c.nextDeadline) <= 30 ? 'text-rose-600' : 'text-[#0B1F3A]'}">${c.nextDeadline ? esc(fmtDay(c.nextDeadline)) : '<span class="text-gray-400">Rolling</span>'}</dd></div>
                </dl>
                <div class="mt-4 flex gap-2">
                    <button type="button" data-open="${c.key}" class="flex-1 rounded-xl border border-gray-200 bg-white px-3 py-2 text-sm font-bold text-[#0B1F3A] transition hover:border-[#0B1F3A]">Details</button>
                    <a href="${enquireHref(c)}" class="flex-1 rounded-xl bg-[#0B1F3A] px-3 py-2 text-center text-sm font-bold text-white transition hover:bg-[#16305A]">Enquire</a>
                </div>
            </div>
        </article>`;
    }

    function enquireHref(c) {
        const p = new URLSearchParams({ course: c.name, university: c.uni, country: c.country, level: c.level });
        return `contact.html?${p.toString()}`;
    }

    /* ---------- render ---------- */
    let openKey = null;
    function render({ keepPage = false } = {}) {
        if (!keepPage) state.shown = PAGE_SIZE;
        const filtered = courses.filter(c => matches(c)).sort(SORTERS[state.sort] || SORTERS.recommended);

        const total = filtered.length;
        const unis = new Set(filtered.map(c => c.uni)).size;
        $('course-count').innerHTML = total
            ? `<strong class="text-[#0B1F3A]">${fmtInt(total)}</strong> ${total === 1 ? 'course' : 'courses'} at <strong class="text-[#0B1F3A]">${fmtInt(unis)}</strong> ${unis === 1 ? 'institution' : 'institutions'}`
            : 'No matching courses';

        const grid = $('course-grid');
        grid.className = state.view === 'list' ? 'cf-card-list gap-5' : 'grid gap-5 sm:gap-6 [grid-template-columns:repeat(auto-fill,minmax(min(100%,19rem),1fr))]';
        grid.innerHTML = filtered.slice(0, state.shown).map(card).join('');
        grid.classList.toggle('hidden', total === 0);
        $('course-empty').classList.toggle('hidden', total > 0);

        const pager = $('cf-pager');
        const shown = Math.min(state.shown, total);
        pager.classList.toggle('hidden', total === 0);
        pager.classList.toggle('flex', total > 0);
        $('cf-pager-text').textContent = `Showing ${fmtInt(shown)} of ${fmtInt(total)} courses`;
        $('cf-pager-bar').style.width = `${total ? (shown / total) * 100 : 0}%`;
        $('cf-more').classList.toggle('hidden', shown >= total);

        $('course-search').value = state.q;
        $('cf-sort').value = state.sort;
        document.querySelectorAll('[data-view]').forEach(b => {
            const on = b.dataset.view === state.view;
            b.setAttribute('aria-pressed', String(on));
            b.classList.toggle('bg-[#0B1F3A]', on);
            b.classList.toggle('text-white', on);
        });
        $('cf-saved-count').textContent = saved.size;
        const savedBtn = $('cf-saved-toggle');
        savedBtn.setAttribute('aria-pressed', String(state.saved));
        savedBtn.classList.toggle('border-rose-300', state.saved);
        savedBtn.classList.toggle('bg-rose-50', state.saved);

        updateFacetPanel();
        activeFilters();
        writeUrl(openKey);
    }

    /* ---------- destinations & stats ---------- */
    function renderDestinations() {
        const countries = Object.keys(COUNTRY_META).filter(k => courses.some(c => c.country === k));
        const maxCourses = Math.max(...countries.map(k => courses.filter(c => c.country === k).length));
        // Balanced rows for 5 destinations: tablet 2+2+1 (last spans the row),
        // laptop 3+2 on a 6-column grid (bottom two wider), wide screens 5 in a row.
        const SPAN_TOP = 'lg:col-span-2 2xl:col-span-1';
        const SPAN_BOTTOM = 'lg:col-span-3 2xl:col-span-1';
        const SPAN_LAST_ODD = 'sm:col-span-2 lg:col-span-3 2xl:col-span-1';
        const spanFor = (i, n) => (n === 5 ? (i < 3 ? SPAN_TOP : i === 4 ? SPAN_LAST_ODD : SPAN_BOTTOM) : '');
        $('cf-destinations').innerHTML = countries.map((k, i) => {
            const meta = COUNTRY_META[k];
            const list = courses.filter(c => c.country === k);
            const unis = new Set(list.map(c => c.uni)).size;
            const fields = [...list.reduce((m, c) => m.set(c.field, (m.get(c.field) || 0) + 1), new Map())]
                .filter(([f]) => f !== 'Other').sort((a, b) => b[1] - a[1]).slice(0, 2).map(([f]) => f);
            return `
            <button type="button" data-country-card="${k}" class="group ${spanFor(i, countries.length)} min-w-0 rounded-2xl border border-slate-200/80 bg-white p-5 text-left shadow-sm transition hover:-translate-y-0.5 hover:border-[#C9A45C]/60 hover:shadow-lg">
                <div class="mb-4 flex items-center gap-3">
                    <span class="flex h-10 w-10 items-center justify-center rounded-xl" style="background:${meta.tint};color:${meta.color}"><i class="fas ${meta.icon}" aria-hidden="true"></i></span>
                    <div class="flex-1">
                        <p class="font-extrabold text-[#0B1F3A]">${esc(meta.name)}</p>
                        <p class="text-xs text-gray-500">${fmtInt(list.length)} courses · ${fmtInt(unis)} institutions</p>
                    </div>
                    <i class="fas fa-arrow-right text-sm text-gray-300 transition group-hover:translate-x-1 group-hover:text-[#C9A45C]" aria-hidden="true"></i>
                </div>
                <dl class="space-y-2.5">
                    ${data.levels.map(level => {
                        const n = list.filter(c => c.level === level).length;
                        return `<div>
                            <div class="mb-1 flex items-baseline justify-between text-xs"><dt class="text-gray-500">${esc(level)}</dt><dd class="font-bold text-[#0B1F3A]">${fmtInt(n)}</dd></div>
                            <div class="h-1.5 overflow-hidden rounded-full bg-gray-100"><div class="h-full rounded-full" style="width:${Math.max(4, (n / maxCourses) * 100 * 1.8).toFixed(1)}%;max-width:100%;background:${meta.color}"></div></div>
                        </div>`;
                    }).join('')}
                </dl>
                ${fields.length ? `<p class="mt-4 text-xs text-gray-500">Popular: <span class="font-semibold text-gray-700">${fields.map(esc).join(', ')}</span></p>` : ''}
            </button>`;
        }).join('');
    }

    function renderStats() {
        const values = {
            courses: courses.length,
            universities: new Set(courses.map(c => c.uni)).size,
            fields: new Set(courses.map(c => c.field)).size,
            countries: new Set(courses.map(c => c.country)).size,
        };
        const reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
        document.querySelectorAll('[data-stat]').forEach(el => {
            const target = values[el.dataset.stat] ?? 0;
            if (reduce) { el.textContent = fmtInt(target); return; }
            const start = performance.now();
            const step = now => {
                const t = Math.min(1, (now - start) / 900);
                el.textContent = fmtInt(Math.round(target * (1 - Math.pow(1 - t, 3))));
                if (t < 1) requestAnimationFrame(step);
            };
            requestAnimationFrame(step);
        });
        const updated = data.generatedAt ? new Date(data.generatedAt) : null;
        if (updated && !Number.isNaN(updated.getTime())) {
            const text = `${updated.getDate()} ${MONTHS[updated.getMonth()]} ${updated.getFullYear()}`;
            $('cf-updated').textContent = `Catalogue updated ${text}`;
            $('cf-updated-note').textContent = `last updated ${text}`;
        }
        const topFields = [...courses.reduce((m, c) => m.set(c.field, (m.get(c.field) || 0) + 1), new Map())]
            .filter(([f]) => f !== 'Other').sort((a, b) => b[1] - a[1]).slice(0, 5);
        $('cf-quick').innerHTML = '<span class="py-1.5 text-blue-200">Popular:</span>' + topFields.map(([f]) =>
            `<button type="button" data-quick-field="${esc(f)}" class="rounded-full border border-white/20 bg-white/10 px-3 py-1.5 text-blue-50 transition hover:bg-white/20"><i class="fas ${FIELD_ICONS[f]} mr-1.5 text-[#E3C88A]" aria-hidden="true"></i>${esc(f)}</button>`
        ).join('') + '<button type="button" data-quick-level="MBA" class="rounded-full border border-white/20 bg-white/10 px-3 py-1.5 text-blue-50 transition hover:bg-white/20"><i class="fas fa-briefcase mr-1.5 text-[#E3C88A]" aria-hidden="true"></i>MBA</button>';
    }

    /* ---------- detail dialog ---------- */
    function summaryBlock(c, html, loading) {
        if (loading) {
            return `<div class="space-y-2" aria-busy="true"><div class="cf-skeleton h-3.5 rounded"></div><div class="cf-skeleton h-3.5 w-11/12 rounded"></div><div class="cf-skeleton h-3.5 w-4/5 rounded"></div></div>`;
        }
        if (html) {
            // Summaries are sanitised at build time to <p>, <h4>, <ul>/<ol>/<li>, <strong>, <em>.
            return `<div class="cf-summary" data-collapsed="true"><div class="cf-summary-body">${html}</div></div>
                <button type="button" data-summary-toggle class="mt-2 hidden text-sm font-semibold text-[#8A6A32] hover:underline">Read more</button>`;
        }
        return `<p class="text-sm text-gray-600">A detailed overview of this ${esc(c.level.toLowerCase())} program in ${esc(c.field.toLowerCase())} at ${esc(c.uni)} is available from our counsellors — ask us for the full course outline, modules and entry requirements.</p>`;
    }

    function setupSummaryToggle() {
        const wrap = document.querySelector('#cf-modal .cf-summary');
        const btn = document.querySelector('#cf-modal [data-summary-toggle]');
        if (!wrap || !btn) return;
        const body = wrap.querySelector('.cf-summary-body');
        if (body.scrollHeight > 230) {
            btn.classList.remove('hidden');
            btn.onclick = () => {
                const collapsed = wrap.dataset.collapsed === 'true';
                wrap.dataset.collapsed = String(!collapsed);
                btn.textContent = collapsed ? 'Show less' : 'Read more';
            };
        } else {
            wrap.dataset.collapsed = 'false';
        }
    }

    function openCourse(key) {
        const c = courses.find(x => x.key === key);
        const dialog = $('cf-modal');
        if (!c || !dialog || typeof dialog.showModal !== 'function') return;
        const scroller = () => {
            const body = $('cf-modal-body');
            return body.scrollHeight > body.clientHeight ? body : dialog.querySelector('.cf-modal-scroll');
        };
        const keepScroll = dialog.open && openKey === key && dialog.querySelector('.cf-modal-scroll') ? scroller().scrollTop : 0;
        openKey = key;
        const meta = COUNTRY_META[c.country] || { name: c.country, icon: 'fa-globe', guide: 'study-abroad/index.html' };
        const isSaved = saved.has(c.key);
        const intakeRows = c.intakes.length ? c.intakes.map(i => {
            const days = i.deadline ? daysUntil(i.deadline) : null;
            const status = days == null ? ['Rolling', 'text-gray-500']
                : days < 0 ? ['Closed', 'text-gray-400']
                    : days <= 30 ? ['Closing soon', 'text-rose-600']
                        : ['Open', 'text-emerald-700'];
            return `<tr class="border-t border-gray-100">
                <td class="py-2.5 pr-3 font-semibold text-[#0B1F3A]">${esc(fmtMonth(i.start))}</td>
                <td class="py-2.5 pr-3 text-gray-600">${i.deadline ? esc(fmtDay(i.deadline)) : '—'}</td>
                <td class="py-2.5 text-right text-xs font-semibold ${status[1]}">${status[0]}</td>
            </tr>`;
        }).join('') : '<tr><td colspan="3" class="py-3 text-gray-500">Upcoming intake dates to be confirmed — ask our team for the latest schedule.</td></tr>';

        const fact = (label, value, icon) => `<div class="min-w-0 rounded-2xl bg-[#F5F6F8] p-3 sm:p-4"><dt class="mb-1 text-xs font-semibold uppercase tracking-wider text-gray-500"><i class="fas ${icon} mr-1.5 text-[#A9813F]" aria-hidden="true"></i>${label}</dt><dd class="text-sm font-bold text-[#0B1F3A]">${value}</dd></div>`;
        const waText = encodeURIComponent(`Hi LGA Visa, I'm interested in ${c.name} (${c.level}) at ${c.uni}, ${meta.name}. Can you help me apply?`);

        $('cf-modal-body').innerHTML = `
            <header class="relative bg-gradient-to-br from-[#0B1F3A] to-[#16305A] px-5 pb-5 pt-5 text-white sm:px-8 sm:pb-6 sm:pt-6" data-country="${esc(c.country)}">
                <span class="mx-auto -mt-2 mb-3 block h-1 w-10 rounded-full bg-white/30 sm:hidden" aria-hidden="true"></span>
                <button type="button" data-close class="absolute right-3 top-3 flex h-10 w-10 items-center justify-center rounded-full bg-white/10 text-white transition hover:bg-white/20 sm:right-4 sm:top-4" aria-label="Close"><i class="fas fa-xmark" aria-hidden="true"></i></button>
                <div class="mb-3 flex items-center gap-3 pr-11 sm:mb-4">
                    ${logoBox(c, 'h-11 w-11 sm:h-12 sm:w-12', 'text-sm sm:text-base')}
                    <div class="min-w-0">
                        <a href="${c.uniHref}" class="block truncate font-bold hover:underline">${esc(c.uni)}</a>
                        <p class="truncate text-xs text-blue-200 sm:text-sm"><i class="fas ${meta.icon} mr-1" aria-hidden="true"></i>${esc([c.city, c.province, meta.name].filter(Boolean).join(', '))}</p>
                    </div>
                </div>
                <p class="mb-1.5 text-xs font-bold uppercase tracking-wider text-[#E3C88A]">${esc(c.level)} · ${esc(c.field)}</p>
                <h2 id="cf-modal-title" class="text-lg font-extrabold leading-snug sm:text-2xl sm:leading-tight">${esc(c.name)}</h2>
            </header>
            <div class="cf-modal-scroll px-5 py-5 sm:px-8 sm:py-6">
                <dl class="mb-6 grid grid-cols-2 gap-2.5 sm:gap-3 md:grid-cols-4">
                    ${fact('Study level', esc(c.level), 'fa-user-graduate')}
                    ${fact('Duration', esc(durationText(c.dMin, c.dMax)), 'fa-hourglass-half')}
                    ${fact('Next intake', c.nextIntake ? esc(fmtMonth(c.nextIntake.start)) : 'TBC', 'fa-calendar-check')}
                    ${fact('Institution', esc(c.uniType), 'fa-building-columns')}
                </dl>
                <h3 class="mb-2 font-bold text-[#0B1F3A]"><i class="fas fa-book-open mr-2 text-[#C9A45C]" aria-hidden="true"></i>Program overview</h3>
                <div id="cf-summary-slot" class="mb-6">${summaryBlock(c, null, c.hasSummary)}</div>
                <h3 class="mb-2 font-bold text-[#0B1F3A]"><i class="fas fa-calendar-days mr-2 text-[#C9A45C]" aria-hidden="true"></i>Upcoming intakes</h3>
                <div class="mb-6 overflow-x-auto">
                    <table class="w-full text-sm">
                        <thead><tr class="text-left text-xs uppercase tracking-wider text-gray-400"><th class="pb-2 font-semibold">Starts</th><th class="pb-2 font-semibold">Apply by</th><th class="pb-2 text-right font-semibold">Status</th></tr></thead>
                        <tbody>${intakeRows}</tbody>
                    </table>
                </div>
                ${c.campuses.length > 1 ? `<h3 class="mb-2 font-bold text-[#0B1F3A]"><i class="fas fa-location-dot mr-2 text-[#C9A45C]" aria-hidden="true"></i>Available at ${c.campuses.length} campuses</h3><p class="mb-6 text-sm text-gray-600">${c.campuses.map(esc).join(' · ')}</p>` : ''}
                ${c.officialUrl ? `<p class="-mt-3 mb-6 text-sm"><a href="${esc(c.officialUrl)}" target="_blank" rel="noopener" class="font-semibold text-[#8A6A32] hover:underline">View the official course page <i class="fas fa-arrow-up-right-from-square ml-1 text-xs" aria-hidden="true"></i></a></p>` : ''}
                <a href="${c.uniHref}" class="mb-6 flex items-center gap-3 rounded-2xl border border-gray-100 p-4 transition hover:border-[#C9A45C]/60 hover:bg-[#FBF7EE]" data-country="${esc(c.country)}">
                    ${logoBox(c, 'h-10 w-10')}
                    <span class="min-w-0 flex-1"><span class="block truncate text-sm font-bold text-[#0B1F3A]">About ${esc(c.uni)}</span><span class="block text-xs text-gray-500">Campus, institution details and all listed courses</span></span>
                    <i class="fas fa-arrow-right text-sm text-[#C9A45C]" aria-hidden="true"></i>
                </a>
                <div class="rounded-2xl border border-[#C9A45C]/30 bg-[#FBF7EE] p-4 text-sm text-gray-700">
                    <p class="mb-1 font-bold text-[#0B1F3A]">What we'll check for you</p>
                    <p>Entry requirements for Sri Lankan qualifications (A/L, diploma or degree), English test scores (IELTS / PTE), application documents and the ${esc(meta.name)} student visa process.</p>
                </div>
            </div>
            <footer class="flex flex-col gap-3 border-t border-gray-100 bg-white px-5 py-4 sm:flex-row sm:items-center sm:px-8">
                <div class="flex flex-1 flex-wrap items-center gap-x-4 gap-y-1 text-sm">
                    <a href="${meta.guide || 'study-abroad/index.html'}" class="font-semibold text-[#8A6A32] hover:underline">Study in ${esc(meta.name)} guide</a>
                    <button type="button" data-save="${c.key}" class="font-semibold ${isSaved ? 'text-rose-600' : 'text-gray-600'} hover:underline" aria-pressed="${isSaved}"><i class="fa${isSaved ? 's' : 'r'} fa-heart mr-1" aria-hidden="true"></i>${isSaved ? 'Saved' : 'Save'}</button>
                </div>
                <div class="grid grid-cols-[auto_minmax(0,1fr)] gap-2 sm:flex">
                    <a href="https://wa.me/94717225223?text=${waText}" target="_blank" rel="noopener" class="inline-flex items-center justify-center gap-2 rounded-xl border border-emerald-600 px-4 py-2.5 text-sm font-bold text-emerald-700 transition hover:bg-emerald-50" aria-label="Ask about this course on WhatsApp"><i class="fab fa-whatsapp text-base" aria-hidden="true"></i><span class="hidden min-[380px]:inline">WhatsApp</span></a>
                    <a href="${enquireHref(c)}" class="inline-flex items-center justify-center gap-2 whitespace-nowrap rounded-xl bg-[#0B1F3A] px-5 py-2.5 text-sm font-bold text-white transition hover:bg-[#16305A]"><span>Enquire<span class="hidden sm:inline"> about this course</span></span><i class="fas fa-arrow-right" aria-hidden="true"></i></a>
                </div>
            </footer>`;
        if (!dialog.open) {
            dialog.showModal();
            document.documentElement.classList.add('overflow-hidden');
        }
        scroller().scrollTop = keepScroll;
        writeUrl(openKey);

        if (c.hasSummary) {
            loadSummaries(c.uniId).then(summaries => {
                if (openKey !== key) return;
                const slot = $('cf-summary-slot');
                if (!slot) return;
                slot.innerHTML = summaryBlock(c, summaries[key], false);
                setupSummaryToggle();
            });
        }
    }

    function closeCourse() {
        const dialog = $('cf-modal');
        if (dialog.open) dialog.close();
    }

    /* ---------- events ---------- */
    function toggleSave(key) {
        if (saved.has(key)) saved.delete(key); else saved.add(key);
        storage.write(saved);
        render({ keepPage: true });
        if (openKey === key) {
            // Update only the Save control so the loaded summary stays in place.
            const btn = document.querySelector('#cf-modal footer [data-save]');
            const on = saved.has(key);
            if (btn) {
                btn.setAttribute('aria-pressed', String(on));
                btn.className = `font-semibold ${on ? 'text-rose-600' : 'text-gray-600'} hover:underline`;
                btn.innerHTML = `<i class="fa${on ? 's' : 'r'} fa-heart mr-1" aria-hidden="true"></i>${on ? 'Saved' : 'Save'}`;
            }
        }
    }

    function setFiltersOpen(open) {
        $('cf-filters-panel').classList.toggle('cf-open', open);
        $('cf-filters-backdrop').classList.toggle('hidden', !open);
        document.body.classList.toggle('overflow-hidden', open);
    }

    function clearAll() {
        state.q = '';
        FACETS.forEach(f => state[f].clear());
        state.uni = '';
        state.saved = false;
        render();
    }

    function scrollToFinder() {
        $('finder').scrollIntoView({ behavior: window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth' });
    }

    function bindEvents() {
        let searchTimer;
        $('course-search').addEventListener('input', e => {
            clearTimeout(searchTimer);
            searchTimer = setTimeout(() => { state.q = e.target.value.trim(); render(); }, 150);
        });
        $('cf-hero-form').addEventListener('submit', e => {
            e.preventDefault();
            state.q = $('cf-hero-search').value.trim();
            render();
            scrollToFinder();
        });
        $('cf-sort').addEventListener('change', e => { state.sort = e.target.value; render(); });

        $('cf-facets').addEventListener('change', e => {
            const input = e.target;
            if (!input.dataset.facet) return;
            const set = state[input.dataset.facet];
            if (input.checked) set.add(input.value); else set.delete(input.value);
            render();
        });
        $('cf-facets').addEventListener('click', e => {
            const btn = e.target.closest('[data-month]');
            if (!btn) return;
            const m = btn.dataset.month;
            if (state.month.has(m)) state.month.delete(m); else state.month.add(m);
            render();
        });

        document.addEventListener('click', e => {
            const t = e.target.closest('[data-action], [data-remove], [data-save], [data-open], [data-view], [data-country-card], [data-quick-field], [data-quick-level], [data-close]');
            if (!t) return;
            if (t.dataset.action === 'clear') clearAll();
            else if (t.dataset.remove) {
                const f = t.dataset.remove;
                if (f === 'q') state.q = '';
                else if (f === 'saved') state.saved = false;
                else if (f === 'uni') state.uni = '';
                else state[f].delete(t.dataset.value);
                render();
            } else if (t.dataset.save) toggleSave(t.dataset.save);
            else if (t.dataset.open) openCourse(t.dataset.open);
            else if (t.dataset.view) {
                state.view = t.dataset.view;
                try { localStorage.setItem('lga-course-view', state.view); } catch (err) { /* ignore */ }
                render({ keepPage: true });
            } else if (t.dataset.countryCard) {
                state.country = new Set([t.dataset.countryCard]);
                render();
                scrollToFinder();
            } else if (t.dataset.quickField) {
                state.field = new Set([t.dataset.quickField]);
                render();
                scrollToFinder();
            } else if (t.dataset.quickLevel) {
                state.level = new Set([t.dataset.quickLevel]);
                render();
                scrollToFinder();
            } else if (t.hasAttribute('data-close')) closeCourse();
        });

        $('cf-more').addEventListener('click', () => { state.shown += PAGE_SIZE; render({ keepPage: true }); });
        $('cf-saved-toggle').addEventListener('click', () => { state.saved = !state.saved; render(); });
        $('cf-filters-open').addEventListener('click', () => setFiltersOpen(true));
        $('cf-filters-close').addEventListener('click', () => setFiltersOpen(false));
        $('cf-filters-backdrop').addEventListener('click', () => setFiltersOpen(false));

        const dialog = $('cf-modal');
        dialog.addEventListener('click', e => { if (e.target === dialog) closeCourse(); });
        dialog.addEventListener('close', () => {
            openKey = null;
            document.documentElement.classList.remove('overflow-hidden');
            writeUrl(null);
        });
    }

    /* ---------- init ---------- */
    function initialize() {
        if (!$('course-grid')) return;
        data = window.LGA_COURSE_DATA;
        if (!data || !Array.isArray(data.courses)) {
            $('course-grid').innerHTML = '<p class="col-span-full rounded-2xl bg-white p-8 text-center text-red-700">The course catalogue could not be loaded. Please refresh the page or contact LGA Visa for assistance.</p>';
            $('course-count').textContent = 'Catalogue unavailable';
            return;
        }
        courses = buildCourses(data);
        recommendedOrder(courses);
        saved = storage.read();

        const deepLink = readUrl();
        buildFacetPanel();
        renderStats();
        renderDestinations();
        bindEvents();
        render();
        if (deepLink) openCourse(deepLink);
    }

    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', initialize);
    else initialize();
})();
